import{_ as r,a as e,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 25 无妄：真实行事，也承认意外至27 颐：谁在养我，我又养什么","description":"对读《周易》与《周易正义》，逐爻理解第二十五至第三十二卦的无妄、积养、重险、光明、感应与恒久。","frontmatter":{"title":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 25 无妄：真实行事，也承认意外至27 颐：谁在养我，我又养什么","description":"对读《周易》与《周易正义》，逐爻理解第二十五至第三十二卦的无妄、积养、重险、光明、感应与恒久。","splitFrom":"life/personal/yijing/hexagrams-25-32.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读四：无妄大畜颐大过至坎离咸恒","summary":"对读《周易》与《周易正义》，逐爻理解第二十五至第三十二卦的无妄、积养、重险、光明、感应与恒久。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒","link":"/life/personal/yijing/hexagrams-25-32"},"next":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 28 大过：超常承担与结构极限至30 离：光明有所依附，也有盛衰","link":"/life/personal/yijing/hexagrams-25-32-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒","link":"/life/personal/yijing/hexagrams-25-32"},"next":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 28 大过：超常承担与结构极限至30 离：光明有所依附，也有盛衰","link":"/life/personal/yijing/hexagrams-25-32-part-02"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-25-32-part-01.md","filePath":"life/personal/yijing/hexagrams-25-32-part-01.md"}'),o={name:"life/personal/yijing/hexagrams-25-32-part-01.md"};function s(i,t,d,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读四-无妄大畜颐大过至坎离咸恒-·-25-无妄-真实行事-也承认意外至27-颐-谁在养我-我又养什么" tabindex="-1">六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 25 无妄：真实行事，也承认意外至27 颐：谁在养我，我又养什么 <a class="header-anchor" href="#六十四卦详读四-无妄大畜颐大过至坎离咸恒-·-25-无妄-真实行事-也承认意外至27-颐-谁在养我-我又养什么" aria-label="Permalink to &quot;六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 25 无妄：真实行事，也承认意外至27 颐：谁在养我，我又养什么&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-25-32">返回分篇目录</a></p><p>本组先读无妄与大畜，再看颐的养、大过的承载极限，随后以坎离结束上经、以咸恒开启下经。上下经的划分不等于“上经只有天道、下经只有人事”：孔颖达在咸卦疏中已经讨论并反对这种过度割裂，因为每个六爻卦都兼涉天地人。</p><p>本文逐卦实际查阅《周易》经传与《周易正义》卷三、卷四对应篇。原文保留古字、繁体，简体解释为本篇概括；疑难处并列读法，不将古注当成唯一译文。大畜“曰閑輿衛”、坎“樽酒簋貳”、离“大耋之嗟”、恒“振恒”等参照《正义》录文，其他页面可能有异体或异文。古籍中的吉凶、疾病与灾害语句不构成现代预测或诊疗依据。</p><h2 id="六十四卦详读四-无妄大畜颐大过至坎离咸恒" tabindex="-1">六十四卦详读四：无妄大畜颐大过至坎离咸恒 <a class="header-anchor" href="#六十四卦详读四-无妄大畜颐大过至坎离咸恒" aria-label="Permalink to &quot;六十四卦详读四：无妄大畜颐大过至坎离咸恒 {#六十四卦详读四-无妄大畜颐大过至坎离咸恒}&quot;">​</a></h2><p>本组先读无妄与大畜，再看颐的养、大过的承载极限，随后以坎离结束上经、以咸恒开启下经。上下经的划分不等于“上经只有天道、下经只有人事”：孔颖达在咸卦疏中已经讨论并反对这种过度割裂，因为每个六爻卦都兼涉天地人。</p><p>本文逐卦实际查阅《周易》经传与《周易正义》卷三、卷四对应篇。原文保留古字、繁体，简体解释为本篇概括；疑难处并列读法，不将古注当成唯一译文。大畜“曰閑輿衛”、坎“樽酒簋貳”、离“大耋之嗟”、恒“振恒”等参照《正义》录文，其他页面可能有异体或异文。古籍中的吉凶、疾病与灾害语句不构成现代预测或诊疗依据。</p><h2 id="gua-25" tabindex="-1">25 无妄：真实行事，也承认意外 <a class="header-anchor" href="#gua-25" aria-label="Permalink to &quot;25 无妄：真实行事，也承认意外 {#gua-25}&quot;">​</a></h2><p><strong>卦符：䷘　上卦：乾 ☰（天、健）　下卦：震 ☳（雷、动）。</strong></p><p><strong>卦辞原文</strong>：无妄：元亨，利貞。其匪正有眚，不利有攸往。</p><p><strong>白话概括</strong>：传统义理读法重不虚妄、不诈伪，行动要合正；经文中的无妄之灾又保留非自己故意招致的意外层次。《正义》以动而能健、众物行实理说明无妄。诚实有其价值，却不能推出诚实者绝不会遭遇不幸，这正是六三值得认真阅读的原因。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：无妄，往吉。</td><td>从不虚妄的起点行动，得吉。它有初始位置的条件，不是对所有后续行为的空白许可。</td></tr><tr><td>六二：不耕穫，不菑畬，則利有攸往。</td><td>涉及耕种、收获和新旧田亩，断句与解释分歧较大。古注有不造作而顺成之读；不可据此主张不劳动而取收益。</td></tr><tr><td>六三：无妄之災，或繫之牛，行人之得，邑人之災。</td><td>有人系牛，行人取走，邑人却遭殃；他人的得利可能转成自己的损失。它打破“受灾必有道德过错”的简单归因。</td></tr><tr><td>九四：可貞，无咎。</td><td>可以固守合宜原则，不为外界偶然变化而妄作。守正也要先知道所守为何。</td></tr><tr><td>九五：无妄之疾，勿藥有喜。</td><td>以非妄所致之疾、不妄加干预为象。此句属于古代占筮与义理语言，不能据它停药、拒诊或推断疾病自愈。</td></tr><tr><td>上九：无妄，行有眚，无攸利。</td><td>即使标举无妄，处在不宜继续行动的位置仍会有灾。动机无恶不保证行动合时。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“天下雷行，物與无妄；先王以茂對時，育萬物。”</p><p><strong>解释</strong>：雷行天下，万物按时生长，先王据此顺时养育，而不任意造作。茂对时强调盛大地配合时宜；现代可借此讨论尊重条件，但不是自然现象直接证明某种政治安排。</p><p><strong>整体读法与误区</strong>：初九往吉与上九行眚，构成最清楚的限制：同一卦名不能取消位置和时机。六三再提醒因果未必公平，六二要求谨慎理解功利之心。把无妄概括为“只要真诚，宇宙就奖励你”，既忽略意外，也容易反过来责备受害者，远不如保留文本的复杂性。</p><p><strong>细读线索</strong>：无妄之灾的牛、行人、邑人构成一个利益与损害分离的场景：得者和受灾者不是同一个人，这比抽象说世事无常更具体。九四可贞与九五勿药则讨论不应因外来变化而添加妄作，上九进一步指出行进可能已经越界。三处都涉及克制，却各有理由。读时可先分清是否有可处理的原因、是否仍有合宜行动空间，再理解为什么原文不总是鼓励积极有为。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%A0%E5%A6%84" target="_blank" rel="noopener noreferrer">《周易·无妄》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E7%84%A1%E5%A6%84" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·无妄》</a>。</p><h2 id="gua-26" tabindex="-1">26 大畜：蓄积、止健与适时施用 <a class="header-anchor" href="#gua-26" aria-label="Permalink to &quot;26 大畜：蓄积、止健与适时施用 {#gua-26}&quot;">​</a></h2><p><strong>卦符：䷙　上卦：艮 ☶（山、止）　下卦：乾 ☰（天、健）。</strong></p><p><strong>卦辞原文</strong>：大畜：利貞，不家食吉，利涉大川。</p><p><strong>白话概括</strong>：艮在上，能止住乾健，故《正义》以能畜止刚健说明大畜；大象又把畜展开为积养德性。“不家食”在古注中联系养贤，使有才德者不困于自食其家。蓄养的意义不是永远收藏力量，而是使之足以承担事务、渡过困难。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：有厲，利已。</td><td>前有危险，停止有利。已是止的意思，旧刻亦可能见形近字，不应误读成利己主义。</td></tr><tr><td>九二：輿說輹。</td><td>车下关键连接部件脱开，暂不能行。“说”读脱；在古注中也可表示主动停进，不必一概理解成事故。</td></tr><tr><td>九三：良馬逐，利艱貞。曰閑輿衛，利有攸往。</td><td>良马驰逐，开始有行进条件。曰、日及闲舆卫有异解：可读作练习车御防卫，王、孔则有防卫限制之释，不能混成唯一训诂。</td></tr><tr><td>六四：童牛之牿，元吉。</td><td>在小牛未能伤人时加上角上的横木，提前限制危害。童牛之告是另一录文，本文从牿。</td></tr><tr><td>六五：豶豕之牙，吉。</td><td>以制约猛豕为象，处理危险的根源。豶有去势之猪的常见读法，王、孔另从禁制解释，不应把解释分歧抹平。</td></tr><tr><td>上九：何天之衢，亨。</td><td>到了天之大道畅通的景象，蓄止转为施展。“何”有感叹等解释，并不意味着积得越久便必定高升。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“天在山中，大畜；君子以多識前言往行，以畜其德。”</p><p><strong>解释</strong>：多记取前人的言论与行为，用来积养德性。读古书不仅搜集好句，也要比较人物如何在具体处境中行动，经过辨别再吸收；识在此有记识之义。</p><p><strong>整体读法与误区</strong>：初、二先止，三可进，四、五从源头止害，上九通达，显示畜与通并非敌对。与<a href="/life/personal/yijing/hexagrams-09-16#gua-09">小畜</a>比较，可看到约束力量不同，施用程度也不同。现代类比可谈储备和训练，但不宜只解释成财富越多越好；资源、制度和德性是否能负担实际行动才是问题。</p><p><strong>细读线索</strong>：大畜将车、马、牛、豕这些带有力量的对象放在不同爻中，约束与释放因阶段而异。车可以暂脱其连接，牛可在未强时加牿，豕则须处理已经显出的伤害能力；上九最后出现大道，说明限制并非终极目的。若只截取止健，容易把大畜讲成压制才能；若只截取利往，又会忽略此前的训练、辨别与控制。全卦的顺序正使两种片面理解相互制约。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E7%95%9C" target="_blank" rel="noopener noreferrer">《周易·大畜》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E5%A4%A7%E7%95%9C" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·大畜》</a>。</p><h2 id="gua-27" tabindex="-1">27 颐：谁在养我，我又养什么 <a class="header-anchor" href="#gua-27" aria-label="Permalink to &quot;27 颐：谁在养我，我又养什么 {#gua-27}&quot;">​</a></h2><p><strong>卦符：䷚　上卦：艮 ☶（山、止）　下卦：震 ☳（雷、动）。颐读 yí，本义与口颊有关。</strong></p><p><strong>卦辞原文</strong>：頤：貞吉。觀頤，自求口實。</p><p><strong>白话概括</strong>：颐讨论养，既观察所养对象，也观察取得养分的方式。《彖》《正义》由口腹扩展到养贤、养民。自求口实并非一律禁止依靠他人，六爻恰恰反复讨论供养关系；关键在关系是否合宜、欲望是否失去尺度。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：舍爾靈龜，觀我朵頤，凶。</td><td>放弃自己的灵龟，却眼看他人鼓动口颊而羡慕。古注以灵龟自养之象说明失去自守，不必转成神秘动物崇拜。</td></tr><tr><td>六二：顛頤，拂經，于丘頤，征凶。</td><td>供养方向倒置、违背通常关系，又向高处求养而不合宜。断句和丘的所指有异，不可一概判定求助可耻。</td></tr><tr><td>六三：拂頤，貞凶，十年勿用，无攸利。</td><td>违背养的正道，固守这种方式会有凶险。长久不能施用，强调偏差深重，十年不作现实期限预测。</td></tr><tr><td>六四：顛頤吉，虎視眈眈，其欲逐逐，无咎。</td><td>同样顛颐，这里因所处关系不同而吉；专注寻求可供养之助，以便施于下。不能只把虎视译成恶意贪欲。</td></tr><tr><td>六五：拂經，居貞吉，不可涉大川。</td><td>自身不足而依赖上者，可以守正安处，却不宜承担超出能力的大险。承认能力边界有其价值。</td></tr><tr><td>上九：由頤，厲吉，利涉大川。</td><td>成为众人所由得养的承担者，责任危险而可吉，可涉大川。供养者也不能忘记自身承载极限。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“山下有雷，頤；君子以慎言語，節飲食。”</p><p><strong>解释</strong>：口既摄取，也表达；因此养不仅关乎吃什么，还关乎说什么、怎样节制。这里是修养原则，不提供具体营养方案，也不能据卦象决定治疗或饮食禁忌。</p><p><strong>整体读法与误区</strong>：六二、六四同有顛颐却一凶一吉，六五、上九分别不可与可以涉大川，最能显示角色条件的重要。问题不在“独立永远好、依靠永远坏”，而在来源、用途和责任是否匹配。现代还可反思信息摄入与言语输出，但这是本篇延伸，不是古文直接谈社交媒体。</p><p><strong>细读线索</strong>：颐的上下皆阳、中间四阴，卦形在传统取象中可联想到口中虚而上下实。这个口的形象足以贯穿自养、求养与养人，却不能因此推出任何人体生理学结论。初九舍自己的灵龟而羡慕他人，六五承认自己所不足，上九承担众养，描写的是三种不同依赖关系。依靠是否适当不能仅看是否来自他人，还要看有没有失去正道，以及是否把负担转嫁给无力承受者。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%A0%A4" target="_blank" rel="noopener noreferrer">《周易·颐》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E9%A0%A4" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·颐》</a>。</p>',37)])])}const f=r(o,[["render",s]]);export{c as __pageData,f as default};
